bool Game::init(std::string& error){if(!SDL_Init(SDL_INIT_VIDEO|SDL_INIT_AUDIO)){error=SDL_GetError();return false;}SDL_GL_SetAttribute(SDL_GL_CONTEXT_MAJOR_VERSION,3);SDL_GL_SetAttribute(SDL_GL_CONTEXT_MINOR_VERSION,3);SDL_GL_SetAttribute(SDL_GL_CONTEXT_PROFILE_MASK,SDL_GL_CONTEXT_PROFILE_CORE);SDL_GL_SetAttribute(SDL_GL_DEPTH_SIZE,24);SDL_GL_SetAttribute(SDL_GL_DOUBLEBUFFER,1);window_=SDL_CreateWindow("SEWERLINE",1278,720,SDL_WINDOW_OPENGL|SDL_WINDOW_RESIZABLE);if(!window_){error=SDL_GetError();return false;}if(!renderer_.init(window_,error))return false;audio_.init();lastTicks_=SDL_GetTicks();return true;}
void Game::shutdown(){audio_.shutdown();renderer_.shutdown();if(window_)SDL_DestroyWindow(window_);SDL_Quit();}
void Game::newGame(uint32_t seed){maze_=std::make_unique<Maze>(15,15,seed);seed_=maze_->seed();player_=Player{};player_.pos=maze_->worldCenter(0);enemies_.clear();for(int c:maze_->enemySpawns()){Enemy e;e.cell=c;e.pos=maze_->worldCenter(c);e.phase=float(c%17)/17;enemies_.push_back(e);}supplies_.clear();for(int c:maze_->supplies()){Supply s;s.cell=c;s.boxHeight=5.8f;supplies_.push_back(s);}renderer_.buildLevel(*maze_);kills_=shots_=0;runTime_=0;creatureSoundCooldown_=1.5f;directorTimer_=4.f;threat_=.18f;flowTarget_=-1;flowField_.clear();playerVelocity_={};weapon_=WeaponAnim::Idle;weaponTime_=0;screen_=Screen::Playing;subtitle_.clear();SDL_SetWindowRelativeMouseMode(window_,true);}
bool Game::event(const SDL_Event&e){if(e.type==SDL_EVENT_QUIT)return false;if(e.type==SDL_EVENT_KEY_DOWN&&!e.key.repeat){keys_[e.key.scancode]=true;int k=e.key.key;if(screen_!=Screen::Playing&&screen_!=Screen::Paused){menuInput(k);return true;}if(k==SDLK_ESCAPE){screen_=screen_==Screen::Paused?Screen::Playing:Screen::Paused;SDL_SetWindowRelativeMouseMode(window_,screen_==Screen::Playing);return true;}if(screen_==Screen::Paused)return true;if(k==SDLK_R&&player_.ammo.loaded<Ammo::Capacity&&player_.ammo.reserve>0&&weapon_==WeaponAnim::Idle){player_.ammo.reload();weapon_=WeaponAnim::Reload;weaponTime_=0;audio_.play(Audio::Reload);}
 if(k==SDLK_E){int si=-1;if(nearestSupplyDistance(&si)<2.2f&&si>=0&&supplies_[si].state==0){supplies_[si].state=1;supplies_[si].timer=0;weapon_=WeaponAnim::Call;weaponTime_=0;setSubtitle("REQUESTING AMMUNITION...",2.2f);audio_.play(Audio::Ring);}else if(maze_&&length(player_.pos-maze_->worldCenter(maze_->exitIndex()))<2.2f){screen_=Screen::Won;SDL_SetWindowRelativeMouseMode(window_,false);audio_.play(Audio::Victory);}}
 }else if(e.type==SDL_EVENT_KEY_UP)keys_[e.key.scancode]=false;else if(e.type==SDL_EVENT_MOUSE_MOTION&&screen_==Screen::Playing){player_.yaw+=e.motion.xrel*.0022f;player_.pitch=std::clamp(player_.pitch-e.motion.yrel*.0018f,-.42f,.42f);}else if(e.type==SDL_EVENT_MOUSE_BUTTON_DOWN&&screen_==Screen::Playing){if(e.button.button==SDL_BUTTON_LEFT)attack();if(e.button.button==SDL_BUTTON_RIGHT&&player_.ammo.total()==0)melee();}return true;}
void Game::menuInput(int key){if(key==SDLK_ESCAPE&&screen_==Screen::Controls){screen_=Screen::Menu;return;}if(key==SDLK_RETURN||key==SDLK_SPACE){if(screen_==Screen::Menu)newGame();else if(screen_==Screen::Dead)newGame(seed_);else if(screen_==Screen::Won)newGame();else if(screen_==Screen::Controls)screen_=Screen::Menu;}if(screen_==Screen::Menu&&key==SDLK_C)screen_=Screen::Controls;if(screen_==Screen::Menu&&key==SDLK_Q){SDL_Event quit{};quit.type=SDL_EVENT_QUIT;SDL_PushEvent(&quit);}}
bool Game::tick(){uint64_t now=SDL_GetTicks();float dt=std::clamp((now-lastTicks_)/1000.f,0.f,.05f);lastTicks_=now;if(screen_==Screen::Playing)update(dt);render();return true;}
void Game::movePlayer(float dt){Vec2 forward{std::sin(player_.yaw),-std::cos(player_.yaw)},right{-forward.y,forward.x},wish{};if(keys_[SDL_SCANCODE_W])wish=wish+forward;if(keys_[SDL_SCANCODE_S])wish=wish-forward;if(keys_[SDL_SCANCODE_D])wish=wish+right;if(keys_[SDL_SCANCODE_A])wish=wish-right;bool moving=length(wish)>.1f,sprint=keys_[SDL_SCANCODE_LSHIFT]||keys_[SDL_SCANCODE_RSHIFT];auto creatureFree=[&](Vec2 p){for(const auto&e:enemies_)if(e.state!=Enemy::Dead&&length(p-e.pos)<.72f)return false;return true;};Vec2 before=player_.pos;if(moving){wish=normalized(wish)*(sprint?4.6f:3.25f)*dt;Vec2 nx={player_.pos.x+wish.x,player_.pos.y};if(maze_->walkable(nx,.32f)&&creatureFree(nx))player_.pos.x=nx.x;Vec2 ny={player_.pos.x,player_.pos.y+wish.y};if(maze_->walkable(ny,.32f)&&creatureFree(ny))player_.pos.y=ny.y;}bool displaced=length(player_.pos-before)>.0001f;if(displaced){player_.bob+=dt*(sprint?12.f:8.f);stepTime_-=dt;if(stepTime_<=0){audio_.play(Audio::Step,.22f);stepTime_=sprint?.28f:.4f;}}else stepTime_=0;}
void Game::update(float dt){runTime_+=dt;Vec2 before=player_.pos;movePlayer(dt);playerVelocity_=(player_.pos-before)*(1.f/std::max(dt,.001f));fireCooldown_=std::max(0.f,fireCooldown_-dt);meleeCooldown_=std::max(0.f,meleeCooldown_-dt);player_.hurtFlash=std::max(0.f,player_.hurtFlash-dt*2);if(weapon_!=WeaponAnim::Idle){weaponTime_+=dt;float duration=weapon_==WeaponAnim::Call?3.4f:weapon_==WeaponAnim::Melee?.45f:weapon_==WeaponAnim::Reload?.55f:.22f;if(weaponTime_>duration){weapon_=WeaponAnim::Idle;weaponTime_=0;}}if(subtitleTime_>0)subtitleTime_-=dt;updateDirector(dt);updateEnemies(dt);updateSupplies(dt);if(length(player_.pos-maze_->worldCenter(maze_->exitIndex()))<1.25f)setSubtitle("[E] CLIMB TO THE STREET",.15f);if(player_.health<=0&&screen_==Screen::Playing){screen_=Screen::Dead;SDL_SetWindowRelativeMouseMode(window_,false);audio_.play(Audio::Death);}}
bool Game::clearShot(Vec2 a,Vec2 b)const{float d=length(b-a);for(float t=0;t<d;t+=.18f)if(!maze_->walkable(a+normalized(b-a)*t,.05f))return false;return true;}
void Game::updateDirector(float dt){
  float health=std::clamp(player_.health/100.f,0.f,1.f),ammo=std::clamp(player_.ammo.total()/24.f,0.f,1.f),elapsed=std::clamp(runTime_/180.f,0.f,1.f);
  threat_=std::clamp(.18f+elapsed*.52f+health*.16f+ammo*.12f-(1.f-health)*.28f,.12f,1.f);
  directorTimer_-=dt;if(directorTimer_>0)return;
  int active=0;for(const auto&e:enemies_)if(e.state==Enemy::Chase||e.state==Enemy::Attack)active++;
  int cap=2+int(std::round(threat_*6.f));
  if(active<cap){
    int pc=maze_->nearestCell(player_.pos);auto field=maze_->flowField(pc);int chosen=-1,bestScore=10000;int ideal=4+int(threat_*4.f);
    for(int i=0;i<(int)enemies_.size();i++)if(enemies_[i].state==Enemy::Idle){int steps=field[enemies_[i].cell];float worldDist=length(enemies_[i].pos-player_.pos);if(steps<3||steps>12||worldDist<11.f||clearShot(player_.pos,enemies_[i].pos))continue;int score=std::abs(steps-ideal);if(score<bestScore){bestScore=score;chosen=i;}}
    if(chosen>=0){enemies_[chosen].state=Enemy::Chase;enemies_[chosen].cooldown=.45f;}
  }
  directorTimer_=12.f-threat_*6.5f;
}
void Game::attack(){if(player_.ammo.total()==0){melee();return;}if(fireCooldown_>0||weapon_==WeaponAnim::Call||weapon_==WeaponAnim::Reload)return;if(player_.ammo.loaded==0){setSubtitle("EMPTY - PRESS R",.8f);return;}player_.ammo.fire();shots_++;fireCooldown_=.28f;weapon_=WeaponAnim::Fire;weaponTime_=0;audio_.play(Audio::Shot);Vec2 f{std::sin(player_.yaw),-std::cos(player_.yaw)};Enemy*best=nullptr;float bestD=35;for(auto&e:enemies_)if(e.state!=Enemy::Dead){Vec2 d=e.pos-player_.pos;float dist=length(d);float aim=dot(normalized(d),f);float lateral=dist*std::sqrt(std::max(0.f,1-aim*aim));if(aim>.985f&&lateral<.65f&&dist<bestD&&clearShot(player_.pos,e.pos)){best=&e;bestD=dist;}}if(best){best->hp-=35;best->hurt=.18f;best->state=best->hp<=0?Enemy::Dead:Enemy::Chase;audio_.play(Audio::Hit);if(best->state==Enemy::Dead){kills_++;audio_.play(Audio::Leech);}}}
void Game::melee(){if(player_.ammo.total()!=0||meleeCooldown_>0||weapon_==WeaponAnim::Call)return;meleeCooldown_=.65f;weapon_=WeaponAnim::Melee;weaponTime_=0;audio_.play(Audio::Melee);Vec2 f{std::sin(player_.yaw),-std::cos(player_.yaw)};for(auto&e:enemies_)if(e.state!=Enemy::Dead){Vec2 d=e.pos-player_.pos;if(length(d)<1.65f&&dot(normalized(d),f)>.62f&&clearShot(player_.pos,e.pos)){e.hp-=20;e.hurt=.2f;e.state=e.hp<=0?Enemy::Dead:Enemy::Chase;if(e.state==Enemy::Dead)kills_++;audio_.play(Audio::Hit);break;}}}
void Game::updateEnemies(float dt){
  int playerCell=maze_->nearestCell(player_.pos);if(playerCell!=flowTarget_){flowTarget_=playerCell;flowField_=maze_->flowField(playerCell);}float nearest=1e9f;creatureSoundCooldown_=std::max(0.f,creatureSoundCooldown_-dt);
  for(int ei=0;ei<(int)enemies_.size();ei++){
    auto&e=enemies_[ei];e.phase+=dt*(1.f+threat_*.25f);e.cooldown-=dt;e.hurt=std::max(0.f,e.hurt-dt);if(e.state==Enemy::Dead)continue;
    float dist=length(e.pos-player_.pos);bool sees=dist<24.f&&clearShot(e.pos,player_.pos);if(e.state==Enemy::Idle&&(dist<11.f||sees))e.state=Enemy::Chase;
    if(e.state==Enemy::Chase||e.state==Enemy::Attack)nearest=std::min(nearest,dist);
    if(e.state==Enemy::Chase){
      if(dist<1.3f&&clearShot(e.pos,player_.pos)){e.state=Enemy::Attack;continue;}
      int ec=maze_->nearestCell(e.pos);e.cell=ec;int next=maze_->flowNext(ec,flowField_);Vec2 target=next==playerCell?player_.pos+playerVelocity_*.12f:maze_->worldCenter(next);if(!maze_->walkable(target,.2f))target=player_.pos;
      Vec2 desired=normalized(target-e.pos),separation{};for(int j=0;j<(int)enemies_.size();j++)if(j!=ei&&enemies_[j].state!=Enemy::Dead){Vec2 away=e.pos-enemies_[j].pos;float d=length(away);if(d>.001f&&d<1.2f)separation=separation+away*(1.f/d)*(1.2f-d);}
      Vec2 direction=normalized(desired+separation*.48f);float speed=(1.55f+threat_*.48f)*(e.hurt>0?.72f:1.f),slice=dt/std::max(1,(int)std::ceil(speed*dt/.09f));int slices=std::max(1,(int)std::ceil(speed*dt/.09f));bool moved=false;
      for(int s=0;s<slices;s++){Vec2 step=direction*(speed*slice),candidate=e.pos+step;if(maze_->walkable(candidate,.31f)){e.pos=candidate;moved=true;continue;}Vec2 slideX{e.pos.x+step.x,e.pos.y},slideY{e.pos.x,e.pos.y+step.y};if(std::abs(step.x)>std::abs(step.y)){if(maze_->walkable(slideX,.31f)){e.pos=slideX;moved=true;}else if(maze_->walkable(slideY,.31f)){e.pos=slideY;moved=true;}}else{if(maze_->walkable(slideY,.31f)){e.pos=slideY;moved=true;}else if(maze_->walkable(slideX,.31f)){e.pos=slideX;moved=true;}}}
      e.stuck=moved?std::max(0.f,e.stuck-dt*2.f):e.stuck+dt;if(e.stuck>.45f){Vec2 center=maze_->worldCenter(ec),recover=e.pos+normalized(center-e.pos)*speed*dt;if(maze_->walkable(recover,.25f))e.pos=recover;e.stuck=0;}
    }
    if(e.state==Enemy::Attack){dist=length(e.pos-player_.pos);if(dist>1.55f||!clearShot(e.pos,player_.pos))e.state=Enemy::Chase;else if(e.cooldown<=0){e.cooldown=1.18f-threat_*.28f;int damage=10+int(threat_*6.f);player_.health=std::max(0,player_.health-damage);player_.hurtFlash=.7f;audio_.play(Audio::PlayerHurt,.7f);setSubtitle("THE LEECH BITES",.5f);}}
  }
  if(nearest<9.5f&&creatureSoundCooldown_<=0){float danger=1.f-nearest/9.5f;audio_.play(Audio::Leech,.18f+danger*.48f);creatureSoundCooldown_=1.8f+(1.f-danger)*2.5f;}
}
void Game::updateSupplies(float dt){for(auto&s:supplies_){s.phase+=dt;if(s.state==1){s.timer+=dt;if(s.timer>1.6f&&s.timer-dt<=1.6f){audio_.play(Audio::Radio);setSubtitle("GOT YOU. SENDING IT DOWN!",1.5f);}if(s.timer>3.0f){s.state=2;s.boxHeight=5.6f;s.boxVy=0;}}else if(s.state==2){s.boxVy-=9.8f*dt;s.boxHeight+=s.boxVy*dt;if(s.boxHeight<=.1f){s.boxHeight=.1f;s.state=3;audio_.play(Audio::Drop);}}else if(s.state==3&&length(player_.pos-maze_->worldCenter(s.cell))<1.15f){s.state=4;player_.ammo.reserve+=12;audio_.play(Audio::Pickup);setSubtitle("12 ROUNDS COLLECTED",1.2f);}}}
float Game::nearestSupplyDistance(int*index)const{float best=1e9f;int bi=-1;for(int i=0;i<(int)supplies_.size();i++){float d=length(player_.pos-maze_->worldCenter(supplies_[i].cell));if(d<best){best=d;bi=i;}}if(index)*index=bi;return best;}
void Game::setSubtitle(std::string s,float t){subtitle_=std::move(s);subtitleTime_=t;}
void Game::render(){if(maze_){std::vector<EnemyView>ev;for(auto&e:enemies_)ev.push_back({e.pos,int(e.state),e.phase,e.state==Enemy::Dead});std::vector<SupplyView>sv;for(auto&s:supplies_)sv.push_back({maze_->worldCenter(s.cell),s.state,s.boxHeight,s.phase});renderer_.begin3D(player_,runTime_);renderer_.drawWorld(*maze_,ev,sv,player_,weapon_==WeaponAnim::Fire?.2f:0);}else{Player p;renderer_.begin3D(p,0);}renderer_.beginUI();
 if(screen_==Screen::Playing||screen_==Screen::Paused){renderer_.rect(8,8,84,20,0xaa16130f);renderer_.text(14,14,1.5f,"HEALTH "+std::to_string(player_.health),0xffd8d8c0);renderer_.rect(324,8,94,20,0xaa16130f);renderer_.text(333,14,1.5f,std::to_string(player_.ammo.loaded)+" / "+std::to_string(player_.ammo.reserve),0xff7bd9e6);renderer_.rect(211,117,5,1,0xffd8d8c0);renderer_.rect(213,115,1,5,0xffd8d8c0);renderer_.weapon(int(weapon_),weaponTime_,player_.bob,player_.ammo.total()==0);int si=-1;if(nearestSupplyDistance(&si)<2.2f&&si>=0&&supplies_[si].state==0)renderer_.text(213,177,1.3f,"[E] REQUEST MORE AMMO",0xffffffff,true);if(subtitleTime_>0)renderer_.text(213,204,1.5f,subtitle_,0xff75e7f1,true);if(player_.hurtFlash>0)renderer_.rect(0,0,426,240,0x662018c8);}
 if(screen_==Screen::Menu){
  renderer_.rect(0,0,426,240,0xff17231b);renderer_.rect(0,0,426,240,0x66030504);renderer_.rect(0,0,426,59,0xcc090d0a);renderer_.rect(0,164,426,76,0xdd090d0a);
  renderer_.text(215,19,5,"SEWERLINE",0xff17120f,true);renderer_.text(213,16,5,"SEWERLINE",0xffb7d3ae,true);renderer_.text(213,53,1.25f,"SURVIVE THE SEWERS. FIND THE EXIT.",0xffc5cec0,true);
  bool pulse=(SDL_GetTicks()/450)%2==0;renderer_.text(213,176,2,"ENTER  PLAY",pulse?0xffffdda0:0xffc9ae7a,true);renderer_.text(213,202,1.4f,"C  CONTROLS       Q  QUIT",0xffb5c0b2,true);renderer_.text(213,225,1,"SAVE YOUR AMMO. KEEP MOVING.",0xff708074,true);
 }
 if(screen_==Screen::Controls){renderer_.rect(0,0,426,240,0xee0b100d);renderer_.text(213,22,3,"CONTROLS",0xff72d3c8,true);renderer_.text(46,60,1.5f,"WASD  MOVE     MOUSE  LOOK",0xffd8d0b4);renderer_.text(46,82,1.5f,"LMB  FIRE / PUNCH WHEN EMPTY",0xffd8d0b4);renderer_.text(46,104,1.5f,"R  RELOAD      E  SUPPLY / EXIT",0xffd8d0b4);renderer_.text(46,126,1.5f,"SHIFT  SPRINT  ESC  PAUSE",0xffd8d0b4);renderer_.text(213,168,1.5f,"ZERO TOTAL AMMO EQUIPS FISTS.",0xff75dce0,true);renderer_.text(213,205,1.5f,"ESC  BACK",0xff9e9277,true);}
 if(screen_==Screen::Paused){renderer_.rect(0,0,426,240,0x99000000);renderer_.text(213,95,4,"PAUSED",0xffd8d0b4,true);renderer_.text(213,135,1.5f,"ESC TO DESCEND",0xff75dce0,true);}
 if(screen_==Screen::Dead||screen_==Screen::Won){renderer_.rect(0,0,426,240,0xdd080a08);renderer_.text(213,45,4,screen_==Screen::Won?"YOU ESCAPED":"YOU DIED",screen_==Screen::Won?0xff78e0c8:0xff7777dc,true);renderer_.text(213,92,1.5f,"TIME  "+std::to_string(int(runTime_))+" SECONDS",0xffd8d0b4,true);renderer_.text(213,112,1.5f,"LEECHES  "+std::to_string(kills_)+"   SHOTS  "+std::to_string(shots_),0xffd8d0b4,true);renderer_.text(213,132,1.5f,"AMMO  "+std::to_string(player_.ammo.total())+"   SEED  "+std::to_string(seed_),0xffd8d0b4,true);renderer_.text(213,181,2,screen_==Screen::Won?"ENTER  NEW MAZE":"ENTER  RESTART THIS SEWER",0xff75dce0,true);}
 renderer_.present();}
